    "desc_de": "Diese kapitale Rothlyt-Auster steckt so fest in Felsenschichten auf dem Meeresgrund, dass man angeblich zuerst die gesamte Ge­steins­schicht an Land ziehen müsste, um sie davon trennen zu können.",
