    "desc_de": "Allgemein wird sie für eine Flusskrabbe gehalten, doch während sich diese Spezies von Aas und Algen ernährt, verschlingt die Meu­chel­mör­de­rin mittelgroße Fische bei lebendigem Leibe, was Zweifel an ihrer\r\nevolutionären\r\nAbstammung nährt.",
