    "desc_de": "Der Sylphenschreck nutzt seine Sprungfähigkeit nur, wenn sich eine Sylphe zu nah an sein Revier wagt. Doch selten führen diese Attacken zu einer ernsthaften Verletzung - es ist, als ob dieser Fallskipper sich lediglich einen Spaß mit den flattrigen Waldbewohnern erlaubt.",
