    "name_de": "Grinser",
    "desc_de": "Der kapitale Velodyna-Karpfen entgeht seinen zweibeinigen Häschern, indem er sich auf furiose Weise windet und so auch gut festgezurrte Haken von der Fangleine reißt. Die dabei unvermeidlich auf seine Maulwinkel wirkenden Kräfte sind der Grund für sein charakteristisches Grinsen.",
