    "name_de": "Hai-Thunfisch",
    "desc_de": "Seinen unorthodoxen und biologisch grob falschen Namen verdankt dieser Kapitale dem berüchtigten Gegeruju, der ihn von einem hohen Steg aus erspähte. Für diesen genialen Einfall bedachten die umstehenden Anhänger des üppig ausgestatteten Lebemannes ihn mit spontanem Applaus.",
