    "id": 7916,
    "name_de": "Wurm von Nym",
    "desc_de": "Ritzzeichnungen, die in Ruinen des äußeren La Noscea gefunden wurden, zeigen, dass bereits die Bewohner des alten Nym von einer aalartigen Kreatur terrorisiert wurden. Ob es sich dabei um ein artgleiches Exemplar des Wurms von Nym oder gar um den gleichen Kapitalen handelt, ließ sich bisher nicht ermitteln.",
