    "name_de": "Rute der Aufseherin",
    "desc_de": "In einem uralten Lalafell-Märchen schwimmt ein Händler-Aal so weit seinen heimatlichen Fluss hinauf, bis er an die Palastpforte der Göttin Azeyma gelangt. Die Aufseherin war so beeindruckt von seiner Leistung, dass sie ihn mit einem Mantel aus gleißendem Sonnenlicht bedachte.",
