    "id": 7922,
    "name_de": "Goblin-Schlächter",
    "desc_de": "Jeder Goblin-Fischer träumt davon, eines Tages diesen blutrünstigen Kapitalbarsch zur Strecke zu bringen. Doch noch ist kein Goblin, der dazu ausgezogen ist, lebend zurückgekehrt. Also bevorzugen die meisten Goblin-Fischer, diesen Traum in der wohligen Sicherheit ihrer Schlafstätte weiterzuträumen.",
