    "desc_de": "Diese fleischfressende Amphibie sondert bei Gefahr ein aromatisches Sekret ab, dass den Angreifer entweder angewidert fliehen lässt oder zum sofortigen Verzehr des Sekrets veranlasst. Flucht ist indes die bessere Wahl,\r\ndenn das Sekret\r\nist hochgiftig.",
