    "name_de": "Knallomat-Fisch",
    "desc_de": "Dieser Kapitale wurde in Anlehnung an den riesigen Nichts­gesand­ten benannt, der die Bewohner Eorzeas in den letzten Tagen der Sechsten Ära des Lichts in Angst und Schrecken versetzte.",
