    "name_de": "Salzling",
    "desc_de": "Dieser Kugelfisch ist äußerst pingelig, was den ihm genehmen Salzgehalt des Wassers angeht. So kreuzt er ständig durch die Gewässer, stets auf der Suche nach dem richtigen Verhältnis zwischen Salz- und Süßwasser. Mal ist es ihm zu süß, mal zu salzig, mal zu mittel.",
