    "desc_de": "Der Einsame Schnitter überwindet seinen angeborenen Instinkt, im Schwarm zu jagen, und verschlingt seine Beute allein - was ihn zu seiner enormen Größe heranwachsen lässt. Am liebsten jagt er bei stürmischem Wetter\r\nin aufgepeitschter See.",
