    "desc_de": "Diese Forelle hat eine verborgene Thermal­quelle am Boden des Bronzesees zu ihrer Heimat auserkoren, wo sie die Tage in lenziger Ruhe verbringt und gelegentlich von dem warmen Wasser angelocktes Kleintier vertilgt.",
