    "desc_de": "Geschichten über Kämpfe, die von auf Dünenmantas reitenden Zauberern ausgetragen wurden, unterhalten die Kinder des Drakon-Stammes an den Lagerfeuern. Die fliegenden Mantas findet man\r\nnoch heute in den\r\nDünen der Sagolii.",
