    "name_de": "Grüne Närrin",
    "desc_de": "Eine Nacht im stinkigen Magen eines nicht weniger stinkenden Morbols war nicht genug, diesem Kapitalen den Garaus zu machen. Wahrscheinlich überstand er diesen Zwischenfall sogar gestärkt, sicher jedoch etwas grüner als zuvor.",
