    "name_de": "Blutbad",
    "desc_de": "Bekannterweise badete Lady Amandine auf ihrer verzweifelten Jagd nach ewiger Jugend im Blute unzähliger Jungfrauen. Eigentlich badete sie in allem, was den Alterungsprozess zu stoppen im Rufe stand. Das galt auch für die\r\narmen Monke Onke.",
