    "desc_de": "Die Sylphen brachten diesen Fisch ihrem Gebieter Ramuh als Opfer dar. Der Herr der Blitze war von dessen Schönheit so beeindruckt, dass er ihm ein neues Leben schenkte und als seinen Sohn aufnahm.",
