    "name_de": "Donnerhall",
    "desc_de": "Donnerhall, eine Groppe von legendärem Appetit, verschlang einer Koboldlegende nach den aus den Wolken schallenden Donner, und dieser übermäßigen Gier sei es zu verdanken, dass die Stürme La Nosceas ohne Ankündigung hereinbrechen.",
