    "name_de": "Spiegelschuppe",
    "desc_de": "Die Schuppen des Silberfisches sind so hochpoliert, dass sich Angreifer oft vor ihrem eigenen gespiegeltem Antlitz erschrecken und die Flucht ergreifen.",
