    "name_de": "Tausend-Jahre-Wels",
    "desc_de": "Die Anhänglichkeit dieses treuen Harnischwels ist legendär. Man sagt, dass der Kapitale einst seinen Besitzer mitsamt Familie auf tausend Jahre verfluchte, weil er ihn kurzerhand an einem sonnigen Nachmittag in einem Bach\r\naussetzte.",
