    "name_de": "Hannibal",
    "desc_de": "Nachdem er alle anderen Fische in seinem Tümpel am Blauen Dunst verspeist hatte, entschied sich Hannibal, auch noch seine Mit-Alligatorhechte zu verzehren. Nach diesem kannibalistischen Akt bleibt ihm keine andere Wahl, als\r\ngelegentlich einen\r\nAngler zu fressen.",
