    "name_de": "Schattensträhne",
    "desc_de": "Seit Generationen erzählen Fischer ihren Söhnen und Enkeln Schauergeschichten von Schattensträhne, dem schrecklichen Hecht. Zehn Yalme lang und fünf Yalme breit, mit einem Maul, das eine hochschwangere Bisonkuh quer verschluckt.",
