    "name_de": "Kapitänskelch",
    "desc_de": "Um es zum echten Piraten zu schaffen, bedarf es mehr als dem gängigen PAH-Kostüm (Papagei, Augenklappe und Hakenarm): Nein, einen echten Seeräuber erkennt man an einem stilechten Behälter für seinen Rum, und was wäre da besser geeignet als die Schale eines riesigen Perlboots?",
