    "name_de": "Neptodrache",
    "desc_de": "Unregelmäßige Ätherströme nach der Siebten Katastrophe veränderten nicht nur die Landschaft, sondern auch seine Bewohner. So wie beim Neptodrachen, einem kleinen Thalaos, der zu riesigen Ausmaßen mutiert ist.",
