    "name_de": "Coelacanthus",
    "desc_de": "Etwas größer, älter und gewiefter als sein Vetter der Quastenflosser. Dieser Tiefseefisch kommt zum Fressen nur in mondlosen Nächten in die Nähe der Was­ser­o­ber­flä­che.",
