    "name_de": "Endoceras",
    "desc_de": "Dieser speerförmige Fisch ist so selten, dass viele Sommer vergehen können, bis er einem glücklichen Fischer ins Netz geht - oder sich aus Versehen in die Planken eines Schiffes bohrt.",
