    "id": 8760,
    "name_de": "Cornelia",
    "desc_de": "So wie die Faustkämpfer in ganz Eorzea sich Geschichten von der mächtigen Cornelia erzählen - der Begründerin ihrer Kampfkunst - so sprechen auch Fischer ehrfurchtsvoll von ihrer Cornelia: einem\r\naggressiven Harnischwels,\r\nder jeden Störenfried\r\nauf den Grund boxt.",
