    "desc_de": "Die Bezeichnung für die gefürchteten Assassinen aus dem Fernen Osten in seinem Namen kommt nicht von ungefähr: Der Ninja-Kampffisch verteidigt sein Revier, indem er alles und jeden verschluckt, der ihm in die Quere kommt - auch seine\r\nArtgenossen.",
