    "id": 8762,
    "name_de": "Canavan",
    "desc_de": "Die meisten Meeresbewohner - mit der Ausnahme von Schildkröten - werden höchstens ein paar Sommer alt. Dieser Morinabaligi hingegen soll schon über hundert Jahre auf dem Buckel haben.\r\nVermutlich liegt das an\r\nseiner bewussten\r\nErnährung.",
