    "name_de": "Killerkuno",
    "desc_de": "Dieser Katfisch steht in ständigem Zwist um Jagdreviere mit Canavan. Killerkuno ist nicht mehr und nicht weniger tödlich als jede andere Kreatur, die sich von niederen Spezies ernährt, aber Fresskuno klang einfach nicht\r\nimposant genug.",
