    "id": 8764,
    "name_de": "Piratenfluch",
    "desc_de": "Der Piratenfluch verdankt seinen Namen Schiffen, die plötzlich riesige Löcher in ihren Bugen hatten, durch die die wertvolle Beute auf den Grund der See sank - gefolgt von Schiff und Mannschaft.",
