    "name_de": "Ndendecki",
    "desc_de": "Diese Wasserschildkröte ließ sich in einer Grotte nieder, in der zufällig auch ein paar Hekatoncheiren hausten. Seitdem terrorisiert sie ihre Nachbarn, indem sie jedem die Männlichkeit abschnippelt, der es wagt, ihr Wasserloch als\r\nLatrine zu benutzen.",
