    "name_de": "Neunschwänzige Fledermaus",
    "desc_de": "Dieser blutsaugende Egel ist berühmt für die peitschenhafte Bewegung mit seinem Schwanz, mit der er seine Beute lähmt, um sich dann genüsslich an ihren schutzlosen Bäuchen festzusaugen.",
