    "name_de": "Zenit-Wootz-Messerfisch",
    "desc_de": "Nach angeblichen Sichtungen von gigantischen Wootz-Messerfischen in einem bläulich gefärbten Tümpel, glaubte man, ein Abenteurer hätte seinen Thavnair-Nebel hineinfallen lassen. Forscher dementierten diese Theorie jedoch mit dem Verweis, dass die Märkte dann längst mit Zenit-Trockenfleisch überschwemmt wären.",
