    "id": 8768,
    "name_de": "Helicoprion",
    "desc_de": "Im Gegensatz zu den meisten anderen eorzäischen Kreaturen hören die Zähne des Helicoprions weder auf zu wachsen, noch fallen sie aus. Das Ergebnis ist ein Maul voller geschwungener Klingen, die wie das Innenleben einer Maschine\r\naus einer längst\r\nvergangenen Zeit wirken.",
