    "name_de": "Blautod",
    "desc_de": "Um in der extremen Kälte von Coerthas zu überleben, schaltet dieser Süßwasserfisch alle nicht zum Überleben notwendigen Körperfunktionen ab und wartet auf dem Seegrund, bis die Sonne das Wasser wärmt und er wieder jagen kann.",
