    "name_de": "Blutroter Knochenzüngler",
    "desc_de": "In dem Wissen, dass seine leuchtend rote Farbe potenzielle Beute warnen könnte, jagt dieser clevere Knochenzüngler nur bei nebeligem Wetter.",
