    "desc_de": "Ursprünglich im Hochlandgebirge von Abalathias Rückgrat beheimatet, sah sich die Coerthische Krabbe durch die Kältewelle nach der Siebten Katastrophe gezwungen, ihren Lebensraum auszuweiten. Gegrillt und mit Zitronensaft beträufelt schmeckt sie ausgezeichnet.",
