    "desc_de": "Der Körper des Seeigels ist rundum mit spitzen Stacheln versehen. Seeigel sollte man nach dem Fang nicht auf dem Eis liegenlassen, da sie mit ihren Stacheln ein Loch ins Eis bohren und zurück ins Wasser entfliehen können.",
