    "desc_de": "Dieser karnivore Fisch wartet in der Regel am Boden seines Gewässers auf Schneefälle und damit niedrigere Temperaturen. Die Kälte lässt die anderen Fische in eine Art Winterstarre verfallen, wodurch sie zu einfachen Beutetieren werden.",
