    "id": 12765,
    "name_de": "Schneegöttin",
    "desc_de": "Dieser Fisch jagt aus­schließ­lich, wenn über dem Wasser ein Schneesturm tobt. In den Märchen, die ihm die Fähigkeit zuschreiben, diese Schneestürme selbst he­rauf­be­schwö­ren zu können, ist er auch als Schneemuse bekannt. Er wird als Verwandter des Stab des Urteils gehandelt, doch diese Annahme entbehrt bisher jeglichem Nachweis.",
