    "desc_de": "Eine Reihe von schlanken, länglichen Organen auf dem Kopf des Fisches, die keinerlei Funktion zu haben scheinen, erwecken den Eindruck einer prächtigen Mähne, weshalb die Hundertflosse im Volksmund auch als „Löwenmaul“ bekannt ist. Vielleicht fehlen ihnen die Bommel am Ende der länglichen Extremitäten, aber aus irgendeinem Grund verabscheuen Mogrys diese Fischart.",
