    "desc_de": "Für gewöhnlich hängt der Braune Bumerang beinahe bewegungslos an den Steilufern der fliegenden Inseln. Entdeckt er jedoch einen vorbeifliegenden Fisch, so stürzt er sich blitzschnell auf ihn, um dann mit seiner Beute im Griff durch geschickte Kopfbewegungen in seine Ausgangsposition zurückzukehren.",
