    "desc_de": "Obwohl dieser Seeigel aus­schließ­lich in den kältesten Regionen Eorzeas vorhanden ist, kann er dort nur im warmen Wasser von Thermal­quellen überleben. In Coerthas ist nachts häufig ein schrilles Heulen zu vernehmen, das nicht selten von Yetis stammt, die beim Waten durch die natürlichen Bäder auf einen der Seeigel getreten sind. ",
