    "desc_de": "Ihr Panzer aus Windkristallen verleiht dieser seltenen Schildkröte die Fähigkeit zum Fliegen. Solange der Panzer intakt bleibt, schwebt sie immer weiter, aber sobald dieser auch nur den kleinsten Kratzer bekommt, fällt sie zurück zu Hydaelyn.",
