    "name_de": "Schwarzmagierfisch",
    "desc_de": "Ähnlich wie der Zaubererfisch, der den feuerelementaren Äther in seinem Körper manipuliert, tut der Schwarzmagierfisch dies mit dem eiselementaren Äther in seinen Kör­per­flüs­sig­kei­ten, um seinen Körper zu kühlen und so in ansonsten tödlicher Lava überleben zu können.",
