    "name_de": "Gespensterfisch",
    "desc_de": "Der Hirnschädel dieses Fisches ist anders als der Rest seines Körpers vollständig transparent und mit einer gelartigen Substanz gefüllt, in der seine Augen schwimmen. Da es auf den drei großen Kontinenten keine auch nur annähernd ähnlichen Lebewesen gibt, liegt die Vermutung nahe, dass dies eine der schrecklichen Kreationen der Allager ist.",
