    "desc_de": "Dieser riesige Fisch ist in Wahrheit nichts weiter als ein Knochenzüngler, der in den sicheren Gewässern des Dravanischen Hinterlands zu enormer Größe herangewachsen ist. Dieses Phänomen hat es jedoch Gelehrten ermöglicht, einen Zusammenhang zwischen der Größe eines Knochenzünglers und der Weichheit seiner Zunge herstellen zu können.",
