    "name_de": "Thaliak-Kaiman",
    "desc_de": "Während die meisten Leute der Gestank von Indigobarschen abschreckt, scheint er auf den Thaliak-Kaiman anziehend zu wirken, was ihn zu seiner Leibspeise macht. Diese Vorliebe hat Indigofischer auf den Plan gerufen, die mit schweren Armbrüsten Jagd auf den Kaiman machen, um die Barsche zu schützen (damit sie selbst mehr davon essen können).",
