    "desc_de": "Obwohl bereits mehrere lebende Exemplare gefangen und für weitere Unter­such­ungen nach Ul'dah gebracht wurden, verleugnen zahlreiche Naturforscher die Existenz von Kreaturen, die in der Lava leben, und tun die Funde ihrer Kollegen als Lügen zur Erlangung von Ruhm ab.",
