    "desc_de": "Alle bekannten Exemplare des Tupuxuara - eine uralte Wyvern-Art - wurden in der ätherochemischen Einrichtung auf Azys Lla entdeckt. Sollte diese Kreatur tatsächlich dem Labor der Allager entstammen, wäre sie mehrere tausend Jahre alt.",
