    "desc_de": "Dem furcht­ein­flößenden Namen zum Trotz saugt dieser Kopffüßer weder Blut, noch verwandelt er sich in eine Fledermaus. Stattdessen handelt es sich um einen recht friedvollen Vertreter des Wolkenmeers.",
