    "name_de": "Sturmjäger",
    "desc_de": "Im Magen des Sturmjägers gärt eine besondere Hefe, die aus seiner Nahrung ein Gas macht, das leichter als Luft ist, und ihm so die Fähigkeit zum Fliegen verleiht. Kurze Gasstöße aus seinem Rektum dienen ihm als Antrieb. Ja, richtig gelesen.",
