    "name_de": "Berserker-Betta",
    "desc_de": "Innerhalb der Betta-Art gilt die Berserker-Betta als besonders hitzig. Obwohl sie kaum eine Chance hat, ihre Beute zu besiegen, greift sie wiederholt Fische an, die drei- oder viermal größer als sie sind. Diese Hartnäckigkeit hält ihren Bestand relativ gering.",
