    "desc_de": "Es war einmal eine magisch begabte Fischerin, die sich mächtig darüber ärgerte, nur zwei Hände zu haben, um ihren reichen Fang einzuholen. Also verzauberte sie einen Eimer, um ihr dabei zu helfen. Dieser sank jedoch auf den Grund eines Sees, als sie die Konzentration verlor, weil ein Flusskrebs an ihren Zehen nagte.",
