    "desc_de": "Nach ihren Lieblings-Meeresfrüchten gefragt, geben neun von zehn Waisenkindern an, Flussgarnelen gegenüber ihren gewöhnlichen Meeres-Artgenossen zu bevorzugen. Eine ist dabei nie genug, und so fordern sie bei diesem Gericht jedes Mal lautstark einen Nachschlag ein.",
