    "desc_de": "Mitunter macht die Natur bereits im ersten Versuch alles richtig - wie bei diesem Raubfisch, der an der Spitze der Nahrungskette steht. In den blutbefleckten Gewässern der Rubinsee gab es für diesen gefräßigen Jäger seit Anbeginn der Zeit keinen Grund, sich anzupassen oder weiterzuentwickeln.",
