    "name_de": "Prisma-Aal",
    "desc_de": "Der Legende nach soll eine reisende Magierin einst von der schillernden Schönheit der Prismenschlucht so fasziniert gewesen sein, dass sie sich einen edlen Schal aus magischen Fäden aller Farben der Schlucht wob, auf dass sie sich für immer an ihre Schönheit erinnern möge. Doch eine Windböe wehte den Schal von ihren Schultern, und als er ins Wasser fiel, verwandelte er sich in einen prächtigen Aal.",
