    "desc_de": "Einst tummelten sich diese farbenfrohen Karpfen zuhauf in Norvrandt, aber die Lichtflut trieb sie an den Rand des Aussterbens. In Crystarium arbeitet man hart daran, diese Fische zu züchten und ihr Fortbestehen zu sichern.",
