    "name_de": "Seenland-Zuckerchen",
    "desc_de": "Lange hat man sich Geschichten davon erzählt, dass diese grünen Kugeln eigentlich bonbonartige Naschereien für riesige Bestien sind. Wer sie kostet, wird allerdings bitter enttäuscht - sie schmecken lediglich nach Algen und sind unangenehm weich.",
