    "name_de": "Xanthismobarsch",
    "desc_de": "Das kräftige Gelb der Schuppen dieses Barschs geht auf eine Melaninanomalie zurück. Was auf der Ursprungs­welt wohl ein Nachteil wäre, schützt den Splitter­welt-Fisch jedoch gegen das gleißende Weiß der Lichtflut.",
