    "id": 27418,
    "name_de": "Skelettseraph",
    "desc_de": "Die Haut dieser Fische ist so durchscheinend, jede einzelne Gräte ist deutlich zu erkennen. Wenn ein Skelettseraph stirbt, verhärtet sich sein Körper und wird zu glasartigem Kristall, das faszinierend-schaurige Innenleben der Kreatur für die Ewigkeit bewahrend.",
