    "id": 27474,
    "name_de": "Wimpelkarpfen",
    "desc_de": "Diese Fischart erkennt man sofort an ihren charakteristischen schwarzen Streifen, die sich über ihr gesamtes Schuppenkleid ziehen. Die Nu Mou erzählen sich, dass diese Tiere eigentlich schneeweiß sind und lediglich von den schelmischen Pixies mit Tinte verziert worden sind.",
    "icon": "./icons/029581.png",
