    "id": 27508,
    "name_de": "Nautilus-Ammonit",
    "desc_de": "Die regenbogenfarbene, schillernde Schale dieses Kopffüßers ist nicht nur für ihre atemberaubende Schönheit bekannt, sondern auch für ihre notorische Seltenheit. Laut altem Aberglauben werden Fischer, die einen Nautilus-Ammonit in ihren Netzen finden, mit ewigwährendem Reichtum gesegnet.",
