    "id": 28070,
    "name_de": "Roter Dämon",
    "desc_de": "Rote Bettas sind ohnehin schon bekannt für ihre hohe Aggressivität, doch dieses besondere Exemplar scheint seine Aggressionen sogar an seinen Artgenossen auszulassen. Der rote Betta ist so gemeingefährlich, dass selbst die Fuath einen weiten Bogen um sein Territorium machen.",
