    "name_de": "Selardisches Tintenfässchen",
    "desc_de": "Die dunkle, lilafarbene Flüssigkeit dieses Bauchfüßlers wird schon seit Urzeiten im Seenland als wertvolles Färbemittel gepriesen. Vor allem beim gebildeten Volk erfreute es sich großer Beliebtheit, so sehr, dass man irgendwann die Farbe selbst mit hoher Bildung und gediegener Weisheit gleichsetzte. ",
