    "desc_de": "Dieser Fisch ist für sein entspanntes Gemüt bekannt und fühlt sich in kühlen Gewässern mit ruhigen Strömungen am wohlsten. Sein Fleisch ist weiß und zart und wird in den Fischer­dörfern Kholusias in allen erdenklichen Variationen verspeist: Roh, getrocknet, geräuchert, gegart, gekocht oder gebraten.",
