    "desc_de": "Die Perlen dieser Muschel sind von sagenumwobener Schönheit. Einer Sage nach wird immer, wenn jemand eine dieser Perlen zu einem Schmuckstück verarbeitet, eine Seele ins Land der Feen entführt. Für manche ein fairer Preis für ein solch exquisites Kleinod.",
