    "name_de": "Araendel",
    "desc_de": "Das schuppenbewehrte Wesen, das übersetzt den Namen „Schild des Landes“ trägt, ähnelt in der Tat einem kriechenden Bollwerk. Seine Schuppen wurden von den Rittern des Hochadels oft für Rüstzeug und Schilde verwendet, sie sind aber seit der Lichtflut ein selten gesehenes Material geworden. ",
