    "name_de": "Kholusische Königskrabbe",
    "desc_de": "Lange glaubte man, dass dieser Was­ser­be­woh­ner von der Lichtflut verschlungen und ausgestorben sei. Bekannt ist er und seine Artgenossen für seine gemächliche Art und für den überraschend süßlichen Geschmack seines Fleisches. Seine Wiederentdeckung ist eine der Sensationen, die zurzeit in Kholusia von sich reden macht. ",
