    "desc_de": "Diese kleine Fischart stammt ursprünglich aus den eisigen Bergseen und Flüssen von Coerthas. Mit dem Schmelzwasser im Frühling gerieten einige Exemplare bis ins Meer, wo sie sich im warmen Wasser und dank des reichhaltigen Nahrungsangebots schnell vermehren.",
