    "name_de": "Matthai",
    "desc_de": "Der Matthai ist ein Verwandter der Silberhaie, die vorwiegend in Südsee-Gewässern heimisch sind. Im Laufe seiner langen Wanderschaften hat er sich an kältere Gefilde angepasst und seine ledrige Schuppenhaut hat ein mattes Grau angenommen, wodurch er von seiner Beute kaum noch vom umgebenden, dunklen Wasser zu unterscheiden ist.",
