    "name_de": "Lebende Laterne",
    "desc_de": "Das intensive Orange dieser Qualle strahlt so sehr, man könnte meinen, unter Wasser treibt eine leuchtende Laterne vor sich hin. In gewissen Teilen der Welt wird sie daher als Glücksbringer geschätzt, gleich einem Licht, das selbst unter den widrigsten Umständen nicht erlöschen will.",
