    "name_de": "Goobbue-Rochen",
    "desc_de": "Während man den Namen dieses Rochens auf seine ausgeprägte Körperform zurückführen könnte, dominiert unter Fischern doch eine gänzlich andere Theorie. Einst liebte eine Goobbue das Meer so sehr, dass sie ihm gar nicht mehr entsteigen wollte. So verwandelte sie sich einfach in einen Fisch und war für immer mit dem kühlen Nass vereint.",
