    "desc_de": "Seinen schaurigen Namen hat dieser Lippenfisch seinem Lebensraum zu verdanken. Doch macht er ihm auch dadurch alle Ehre, dass er sich gerne Kopfstoßkämpfe mit Rivalen liefert, die ihm einen angemessenen rötlichen Teint verleihen.",
