    "desc_de": "Legenden kennen diese Krabben als gänzlich blaue Gesellen, die von dem Neid auf die lackierten Nägel von modebewussten Meerjungfrauen beinahe aufgezehrt wurden. Um diesem Ideal nahe zu kommen, tränken sie seither ihre Zangen im Blut ihrer Beute.",
