    "name_de": "Götterwiege",
    "desc_de": "Die massive Größe dieser Muschel hat die Kreativität zahlreicher Künstler in eine ganz bestimmte Richtung gekitzelt. Auf unzähligen Bildern entsteigt die eine oder andere Meeresgottheit einer eben solchen Muschel - mal mehr bekleidet, mal weniger.",
