    "desc_de": "Dieser Fisch verspeist die Muscheln mitsamt Felsen, an denen sie wachsen. Er kann nur mit einem speziellen Netz gefangen werden und seine messerscharfen Zähne werden ohne weitere Verarbeitung als Klingen verwendet.",
