    "desc_de": "Ein riesiger Tintenfisch, der mit seinen langen Tentakeln Boote umschlingt und auf den Meeresgrund hinabzieht. Er gilt als Verwandter des Ungeheuers, das unter der Schiffbrecher-Insel lebt, und soll einen Groll gegen die Küstenbewohner hegen. ",
