    "desc_de": "Vom Aussehen her ein ganz gewöhnlicher Frosch, der sich allerdings bevorzugt im Salzwasser aufhält. Gerüchte behaupten, er sei aus einem Labor in der Nähe von Frohehalde entwichen.",
