    "id": 31770,
    "name_de": "Feuerspeier",
    "desc_de": "Mit den feurig glitzernden Schuppen versucht dieser Fisch eine geeignete Partnerin anzulocken. Leider macht er damit auch Fressfeinde auf sich aufmerksam, aber das ist wohl ein lohnender Preis für die wahre Liebe.",
