    "id": 33243,
    "name_de": "Zweitgrößte Schlange von Ronka",
    "desc_de": "Die Große Schlange von Ronka wird als gigantisches, geschupptes Monstrum beschrieben, das sich durch den uralten Wald schlängelt. Diese nicht ganz so majestätische Kreatur ist ein deutlicher Hinweis darauf, dass die Große Schlange alsbald zurückkehren wird! Ganz bestimmt!",
    "icon": "./icons/028499.png",
