    "name_de": "Pecten",
    "desc_de": "Diese im Nordmeer heimische Muschelart hat in Sharlayan keinen volkstümlichen Namen erhalten und ist stattdessen nur unter ihrem wissenschaftlichen Namen bekannt, welcher soviel wie Kamm bedeutet.",
