    "name_de": "Nördlicher Hering",
    "desc_de": "Obgleich sehr schmackhaft wenn in Essig eingelegt, wird dieser Fisch noch häufiger getrocknet und zu Fischmehl verarbeitet, das in den Teig für Exegetenbrot eingeknetet wird.",
