    "name_de": "Hundsgesichtiger Kugelfisch",
    "desc_de": "Sein pausbäckiges Gesicht hat entfernte Ähnlichkeit mit einem Hundewelpen. Weniger süß ist er allerdings im Geschmack, da er dermaßen hochgiftig ist, dass Räuber aller Art gebührenden Abstand halten sollten, wenn er gemächlich ihren Weg kreuzt.",
