    "name_de": "Kobalt-Chromis",
    "desc_de": "Seine prächtig strahlenden Schuppen kommen im Meer besonders schön zur Geltung. Wahrscheinlich wurde seine blaue Färbung durch Phantomströme beeinflusst, in denen er sich bevorzugt treiben lässt.",
