    "name_de": "Gitarrenrochen",
    "desc_de": "Obwohl eher unmusikalisch, ist dieser Rochen aufgrund seines langen Schwanzes und rautenförmigen Körpers und der dadurch entstehenden Ähnlichkeit zum Musikinstrument der Lieblingsfisch vieler Gitarrenliebhaber.",
