    "desc_de": "Dieses weit verbreitete Krustentier ist im Sharlayaner Frühsommer ein beliebter Festschmaus. Vermutlich auch deswegen, weil seine Zubereitung denkbar leicht ist: In Salzwasser kochen, herausnehmen, fertig. Zudem kann es einfach in der Hand gegessen werden.",
