    "desc_de": "Wie ein Schwert schneidet dieser Flußbewohner mit enormer Ge­schwindig­keit stromaufwärts durch das Wasser. Auf seiner Wanderung von den Flussmündungen bis zum Oberlauf der Flüsse ernährt er sich von einer Vielzahl kleiner Fische und Krebstiere.",
