    "desc_de": "Dieser Fisch ist an seiner rautenförmigen Form und langen Rückenflosse leicht zu erkennen. Er ist sehr scheu und lebt zurückgezogen in den dunkleren Ecken ruhiger Gewässer, wo er über den Sinn seines Fischdaseins nachzudenken scheint.",
