    "name_de": "Meeres-Dahlie",
    "desc_de": "Dieses Blumentier hat so viele Tentakel, dass es wie eine Dahlie aussieht, die sich im Wasser wiegt. Anders als diese hält es sich jedoch nicht an Felsen oder Steinen fest, sondern rollt auf dem Gewässergrund entlang, wo es reichlich Nahrung findet.",
