    "desc_de": "Diese Karpfenart kann sich allen Umweltbedingungen schnell anpassen. Ihre Zähigkeit veranlasste Forscher, sie in den Gewässern des Labyrinthos freizusetzen, um die Umweltverträglichkeit des Ortes zu bestimmen.",
