    "name_de": "Fundulus",
    "desc_de": "Ein kleiner Fisch, der sehr widerstandsfähig gegenüber Verschmutzungen und Temperaturschwankungen ist. Er ernährt sich vorzugsweise von den Eiern von Insekten in den Fließgewässern, die vom Sammelbecken Nr. 1 aus durch das Labyrinthos strömen.",
