    "name_de": "Tessera",
    "desc_de": "Dieser Buntbarsch ist an seinen langen Streifen leicht zu erkennen. Da seine Pigmentierung und Muster am Leib sich mit der Beschaffenheit seines Habitats verändern, ist er für die Forscher im Labyrinthos von großem Interesse.",
