    "id": 36402,
    "name_de": "Fetter Snook",
    "desc_de": "Diese Snook-Unterart wurde in unterirdischen Anlagen gezüchtet. Ihre Färbung und Körperbau unterscheiden sich von der ihrer oberirdischen Artgenossen, was für diejenigen, die sich für solche Dinge interessieren, zweifellos von Bedeutung und aufschlussreich ist.",
