    "name_de": "Prochilodus Luminosus",
    "desc_de": "Ein leuchtend orangefarbener Fisch mit einer gestreiften Schwanzflosse. Er hat raspelartige Zähne und trägt zur Erhaltung der künstlich erschaffenen Umwelt bei, indem er Moos und Mikroorganismen zu sich nimmt.",
