    "name_de": "Mesonauta",
    "desc_de": "Ein für gewöhnlich einfarbiger und eintöniger Fisch, der sich von seinen Artgenossen nur schwer unterscheiden lässt. Es sei denn, ein Fressfeind nähert sich, dann erscheint ein schwarzer Streifen auf seinem Körper. Wahrscheinlich, damit dieser auch weiß, wen genau er da gleich fressen wird ...",
