    "id": 36405,
    "name_de": "Grünkiemen-Lachs",
    "desc_de": "Auch wenn er durch seine grüne Farbe so aussieht, als würde Moos auf ihm wachsen, und daher einen wenig appetitanregenden Anblick bietet, wird diese im Labyrinthos endemische Art als Kandidat für eine ertragreiche Speisefischzucht gehandelt. Vorausgesetzt, es gelingt, seine maritimen Wanderwege auf ein überschaubares Gebiet zu beschränken.",
