    "desc_de": "Schaut aus wie ein Lachs. Schaut drein wie ein Lachs. Ist aber ein Karpfen. Ein ebenso beeindruckender wie sinnbefreiter Erfolg der Züchter in Sharlayan. Während der Laichzeit färben sich seine ursprünglich bläulichgrünen Schuppen knallrot.",
