    "desc_de": "Die Matanga auf Thavnair lieben diesen Fisch aufgrund seines rüsselartigen Mauls. Der Legende nach hat sich der Fisch einst in eine Arkasodara-Dame verguckt und sich aus Liebe dieses Maul wachsen lassen.",
