    "desc_de": "Diese silberne Lachsart tummelt sich in den Gewässern des Vorgartens des Meghaduta-Tempels. Da er sehr nahr- und schmackhaft ist, ist er gut gewürzt ein fester Bestandteil der königlichen Küche in Radz-at-Han.",
