    "name_de": "Langohren-Sonnenbarsch",
    "desc_de": "Sie zeichnen sich durch Vorsprünge an den hinteren Rändern des Kiemenbeins aus, die stark an Ohren erinnern. Tatsächlich handelt es sich hierbei um einen Teil des Atmungssystems. Je schneller der Fisch schwimmt, desto stärker schlackert der Fisch mit seinen „Ohren“.",
