    "desc_de": "Seit grauer Vorzeit werden diese anmutig silbern schimmernden Fische in Radz-at-Han verehrt. Um eine Überfischung zu vermeiden, ist der Fang an den Fischplätzen in Palastnähe der Familie des Magistrats vorbehalten.",
