    "name_de": "Thavnairische Grundel",
    "desc_de": "Dieser kleine Salz­was­ser­fisch ist in den Gewässern im Süden der Insel Thavnair weit verbreitet. Stets sehr beschäftigt, tummelt sich diese kulinarische Spezialität der Insel in Korallenriffen und nahe der Was­ser­o­ber­flä­che.",
