    "name_de": "Qeyiq-Seezunge",
    "desc_de": "Der Name dieses plattgedrückten Fisches ist ein altes Wort für „Boot“. Wahrscheinlich weil sein Schatten dem eines Bootes ähnelt, wenn er im flachen Wasser kleineren Beutefischen nachstellt.",
