    "id": 36422,
    "name_de": "Gülkrabbe",
    "desc_de": "Die rosenrote Außenschale verschaffte diesem Krustentier seinen Kosenamen - „Rose“. Wenn mehrere von ihnen aufeinanderhocken, kann man sie schon mal mit einer riesigen Blüte in voller Pracht verwechseln. Daran riechen sollte man jedoch besser nicht: Ihre Scheren fungieren als Dornen und giftig sind sie auch.",
