    "id": 36423,
    "name_de": "Pantherzackenbarsch",
    "desc_de": "Am gesamten Körper bis zu den Flossen ist dieser Meeresbewohner mit dunkelbraunen Flecken übersät. Eine Theorie besagt, dass damit die Position der Augen verschleiert werden soll, um Prädatoren zu verwirren.",
