    "id": 36425,
    "name_de": "Gespinst der Frischvermählten",
    "desc_de": "Die schillernden Farben seiner Schuppen erinnern an die bunten Seidengespinste der Insel Thavnair. In Fischer­dörfern ist es Brauch, dass die Braut das Muster eines vom Bräutigam gefangenen Fisches webt und ihre Kreation bei den Feierlichkeiten nach der Hochzeit zur Schau trägt.",
