    "id": 36426,
    "name_de": "Schattensardine",
    "desc_de": "Geboren und herangewachsen in der Tiefsee steigen die adulten Tiere in mittlere Tiefen des Meeres auf, um dort nach Beute zu suchen. Mit dem Bauch nach oben treibend verschmelzen sie mit der Dunkelheit und warten geduldig, bis ein lohnender Happen sich ihnen nähert.",
