    "name_de": "Paksafisch",
    "desc_de": "Diese Sardinenart steht dank ihrer stattlichen Größe und wilden Temperaments an der Spitze des Ökosystems südlich von Thavnair. Es verwundert nicht, dass die Arkasodara ihr den Namen ihres Königs verliehen.",
