    "desc_de": "Eine Berührung seiner Schuppen hinterlässt ein Taubheitsgefühl in der Hand, als hätte man einen elektrischen Schlag bekommen. Tatsächlich erzeugt er Turbulenzen im Ätherstrom, die im Schwarm eine beachtliche Stärke annehmen können.",
