    "desc_de": "Alchemisten aus Daemirs Werk haben diesem Meeresbewohner seine goldenen Schuppen beschert. Ursprünglich sollten sie vollends in Goldmünzen umgewandelt werden, wie diverse Zahlen und Symbole auf seinem Körper nahelegen.",
