    "desc_de": "Mit offenem Maul schwimmt dieser „Milchtrinker“, wie sein Name übersetzt heißt, durchs Leben, das sich vorrangig im Fluss Ksiroda abspielt. So groß wie er ist, muss man fast befürchten, dass er den ganzen Fluss leertrinkt ...",
