    "desc_de": "Nicht nur der griesgrämige Ge­sichts­aus­druck verbindet diesen kapitalen Kaventsmann mit dem Wächter der Tore nach Radz-at-Han. Er greift auch erbarmungslos jeden an, der schwimmend versucht, außerhalb des Tores einen Weg in die Stadt zu finden.",
