    "desc_de": "Wie loderne Flammen leuchten die Flossen dieses Flussbewohners. Ein heißer Stahlklumpen soll aus einem Schmelzofen in Daemirs Werk emporgeschleudert worden, im Fluss gelandet und zum Leben erwacht sein, lautet die wenig wissenschaftliche Erklärung dafür.",
