    "desc_de": "Seine sich prächtig ausbreitenden vielverzweigten Flossen erinnern an die Garleische Kaiserkrone. Um ihre Treue gegenüber dem Regenten unter Beweis zu stellen, sollen die Mitglieder der kaiserlichen Familie untereinander gewetteifert haben, diesen Fisch in ihre Hände zu bekommen.",
