    "desc_de": "Sein schwarz-weißes Strei­fen­mus­ter ist das Erkennungsmerkmal dieses Fisches. Es ist das Ergebnis seiner Anpassung an die vorherschende Farbgebung der Bewässerungskanäle Garlemalds, doch so manch einer hat die weißen Linien auf der Was­ser­o­ber­flä­che mit Straßenmarkierungen verwechselt und ist hineingesprungen.",
