    "desc_de": "Ein großer Wels in hellblauer Farbe, die ihn im Wasser durchsichtig erscheinen lässt. Er bevorzugt den Grund der Gewässer, aber wenn er einmal an die Oberfläche kommt, sorgt er für Aufregung unter den Bewohnern Garlemalds, die befürchten, dass Eisblöcke in die Bewässerungsgräben gespült wurden.",
