    "name_de": "Sternenblauer Guppy",
    "desc_de": "Die Farbe seiner schönen Flossen ähnelt der eines vom Mond aus sichtbaren blauen Planeten. Die Loporrit haben ihn nach einem Naturforscher aus Sharlayan benannt, dessen Namen sie von Besuchern des Mondes erfahren haben.",
