    "name_de": "Lunarer Buntbarsch",
    "desc_de": "Die Farbe dieses Fisches ist ein von einem hellen Gelbton durchsetztes Blau, wodurch er wirkt, als wäre er vom Mondlicht durchflutet. Seine Farbgebung ändert sich leicht, wenn sie sich verschiedenen Ätherschattierungen auf der Mondoberfläche anpasst.",
