    "id": 36466,
    "name_de": "Tränenauge",
    "desc_de": "Die sternenförmigen Muster um seine Augen, die wie Tränen aussehen, sind das hervorstechende Merkmal dieses Fisches. Es heißt, dass er die Trennung von seinen Artgenossen beweint, die vor langer Zeit als Sternenschnuppen nach Hydaelyn gesandt wurden.",
