    "name_de": "Replica Pirarucu",
    "desc_de": "Eine uralte Art, die nach einem alten Konzept neu erschaffen wurde. Der Loporrit, der die Leitung dieses Prozesses innhatte, ging sich zwischendurch mal was zum Mümmeln holen, weshalb Pigmentmutationen aufgetreten sind.",
