    "name_de": "Albdrückerfisch",
    "desc_de": "Durch ihre Fähigkeit, Giftstoffe aus ätherochemischen Quellen zu zersetzen, erhalten diese Fische die für sie lebens­not­wendigen Nährstoffe. Während dieses Prozesses treiben sie jedoch wegen der Giftsstoffe benommen vor sich hin, als würden sie der Welt entsagen wollen.",
