    "name_de": "Schleierschwanz",
    "desc_de": "Die Schuppen haben einen matten Schimmer, der mal braun, mal violett wahrgenommen werden kann. Das kommt daher, weil sich aufgrund chemischer Reaktionen ihrer metallenen Schuppen deren Farbe je nach Beschaffenheit der Umgebung ändert.",
