    "name_de": "Deuteromycota Nr. 987",
    "desc_de": "Zwar haben sie hervorstehende Pilzfäden, die sie fühlerartig schwenken, doch verfügen sie über keinen eigenen Willen und ahmen lediglich Bewegungen anderer Lebewesen nach. Sie gehen Synthesen mit organischen Stoffen in den ätherochemischen Quellen ein, wodurch sie langsam wachsen.",
