    "desc_de": "Diese Art ist mit dem Wüstenfisch Olgoi-Khorkhoi verwandt. Es gibt die Theorie, dass sich die Spezies ursprünglich auf dem Mond entwickelt hat, dann aber von einem Meteoriteneinschlag erfasst und auf Hydaelyn geschleudert wurde.",
