    "desc_de": "Dieser Schmarotzer hat sich in den Spalten des riesigen Panzers einer auf dem Mond heimischen Weltraumschildkröte eingenistet. Seinen großspurigen Namen hat er erhalten, weil er dabei wie ein Schwert aussieht, das in der Mondoberfläche steckt.",
