    "desc_de": "Ihr grauer Panzer ahmt die Mondoberfläche verblüffend genau nach. Die Loporrit wollen einem weismachen, dass der Mond sich tatsächlich aus einer Herde dieser Weltraumkröten zusammensetzt.",
