    "desc_de": "Mit seiner wie ein Blatt aussehenden Rückenflosse fängt er Windäther ein und wandert zu den schwebenden Inseln in Elpis. Vereinzelnd gibt es unter ihnen schlechte Schwimmer, die den Wind nicht einzufangen vermögen und auf dem Erdboden zappeln.",
