    "name_de": "Antheia",
    "desc_de": "Dieser schön anzuschauende Fisch wird von den Bewohnern Elpis' liebevoll „Blumenkrone“ genannt. Hier wurde bei der Schönheit der Körperfarbe bis an die Grenzen der Schöpfungsmagie gegangen.",
