    "name_de": "Colossoma",
    "desc_de": "Die Körperform dieses Fisches ist seitlich abgeflacht, erreicht dafür aber eine beachtliche Höhe. Er frisst gerne Insekten, Wasserpflanzen und Pflanzensamen, die er mit seinen robusten Zähnen zerkleinert.",
