    "name_de": "Smaragdos",
    "desc_de": "Dank seiner grünen Farbe kam dieser Fisch zu seinem Namen. Von Vergleichsstudien dieser prähistorischen Art mit den autochthonen Knochenzünglern verspricht man sich einige Erkenntnisse.",
