    "name_de": "Superstring",
    "desc_de": "Eine Kreatur, deren Tentakel mit dem Glanz unzähliger Sterne gefüllt sein sollen. Wer sie fängt, hält das Schicksal zahlreicher Galaxien in seiner Hand.",
