    "id": 37845,
    "name_de": "Großschwert-Snook",
    "desc_de": "Der silberne scharfkantige Rücken dieses Fisches gleicht einem großen Schwert. Einer Theorie zufolge soll es sich tatsächlich um ein von einem Magiestudenten entworfenes magisches Schwert handeln, das in den Fluss fiel und zu schwimmen lernte. ",
    "icon": "./icons/028538.png",
