    "desc_de": "Die Schwanzflosse dieses prächtigen Fisches wiegt in den Wellen wie die Blütenblätter einer Dahlie im Wind. Scheinbar war sein Schöpfer bemüht, einen Fisch zu erschaffen, welcher der Schönheit der Blumengärten an der Lethe in nichts nachsteht.",
