    "desc_de": "Ursprünglich wuchs diese Seetangsorte nur auf dem Meeresgrund von Tempest. Aufgrund der Beliebtheit ihrer kräftigen, nahrhaften Blätter bei den Bewohnern von Kholusia, bemühte man sich bald, sie in zugänglicheren Gebieten anzubauen.",
