    "desc_de": "Man nimmt an, dass es sich bei dieser herrlich schillernden Muschel um eine kürzlich mutierte Art handelt, die durch Schwankungen der Ätherströmungen auf dem Meeresboden entstanden ist. Sie soll ihren Namen von Bismarck höchstselbst erhalten haben.",
