    "desc_de": "Diese große, schmackhafte Garnelenart findet in der Küche Thavnairs oft als Zutat für Currys Verwendung. Sie werden im Ganzen geröstet und ihre Schalen nach dem Verzehr für alchemistische Zwecke weiterverarbeitet.",
