    "desc_de": "Ein Lebewesen, dem man versuchte, Blätter anzuzüchten, die wie die Flossen eines Fisches paddeln. Obwohl es einer Pflanze ähnelt, führte sein eierlegendes Fortpflanzungsverhalten dazu, dass man es letztlich als Fisch in die Register aufnahm.",
