    "desc_de": "Eine seltene Seepferdchenart, welche dank ihres weiß-silbrigen Körpers unter den Adligen des Seenlandes äußerst begehrt war. Neben seinem Aussehen wird es auch in getrockneter Form als Zutat in der Alchemie verwendet.",
