    "desc_de": "Eine Muränenart heimisch in den Küstengebieten von Kholusia. Aufgrund ihres aggressiven Verhaltens gegenüber jenen, die sich dem Clavis-Leuchturm nähern, werden sie auch von manchen „Schlüsselwächter” genannt und für heilig befunden.",
