    "desc_de": "Es wird gesagt, dass die Prinzessin von Voeburt häufig ihr Gesicht im Kleinen Spiegel betrachtet hat. Angeblich erinnert das Aussehen dieses Fisches an das Muster ihres Kleids und ihre rosaroten Wangen, und auch seine temperamentvolle Art sei der Prinzessin nicht fremd.",
