    "name_de": "Pailletten-Pirarucu",
    "desc_de": "Während der Ronka-Epoche war es zeitweise üblich, sich Münzen wie Schuppen in die Kleidung nähen zu lassen. Aufgrund des ähnlich aussehenden Musters wird dieser Fisch auch als „Ronka-Münze” bezeichnet. Das Glitzern seines Körpers verleiht ihm eine Ausstrahlung von überwältigendem Reichtum.",
