    "desc_de": "Durch seine glänzenden Schuppen wird dieser Fisch oft mit Onyx verglichen. Exemplare in seinem Herkunftsgebiet weisen jedoch keinerlei solche Merkmale auf. Deshalb wird vermutet, dass sein Körper sich seiner jetzigen Umgebung angepasst hat. ",
