    "name_de": "Wachsamer Aufseher",
    "desc_de": "Dieses Exemplar strahlt Würde in seiner reinsten Form aus. Es kommt also nicht von ungefähr, dass es einen ganzen Schwarm Wachsamer Wächter befehligt. Im Himmelsheer wurden sogar Stimmen laut, diesen Fisch zu einem Ehrenmitglied zu machen. Da es nun allerdings gefischt wurde, wird daraus wohl nichts mehr.",
