    "desc_de": "Eine äußerst brutale Bestie, die als Anführer der Dorudon fungiert. Ob Freund oder Feind, wer sich gegen sie wendet, wird von ihren rasiermesserscharfen Zähnen zerfleischt und anschließend genüsslich verspeist.",
