    "id": 39882,
    "name_de": "Eehs Fahn",
    "desc_de": "Diese Abscheulichkeit ist auch als „Flammenfresser“ bekannt. In vergangenen Zeiten verschlang er Drachenfeuer und kehrte dieses wiederum in Lebensenergie für sich um. Sein einziger Lebensinhalt besteht nun in der Suche nach weiterer lebensverlängernder Energie.",
