    "name_de": "Gold-Dermogenys",
    "desc_de": "Ein Dermogenys, dessen Schuppen im Sonnenlicht in blassem Gold erstrahlen. Durch die Wunder der Schöpfungsmagie wurde ein Mikroorganismus auf seiner Körperoberfläche gezüchtet und so angepasst, dass sie eine andere Lumineszenz als die seiner Artgenossen aufweist.",
