    "desc_de": "Diese Sardine nutzt ihre dunkel gefärbten Schuppen, um Feinden in der Nacht zu entkommen. Mittags hingegen ist sie besonders leicht zu entdecken. Daher versteckt sie sich oft bewegungslos im Schatten von Felsen.",
