    "desc_de": "Ihre spiralförmige Schale besitzt die Fähigkeit, den Wasserstrom zu beeinflussen. Wenn sie sich in der Nähe der Was­ser­o­ber­flä­che aufhält, kann es plötzlich passieren, dass Wasserstrudel auftauchen. Die Fischer Kuganes stört dies aber herzlich wenig. Schmeckt besonders gut mit Sojasoße.",
