    "desc_de": "Eine rot-weiß gemusterte Verwandte der Yanxia-Tigergarnele. Ähnlich der Marmorierung von Rindfleisch hat die Farbausprägung angeblich große Auswirkung auf den Geschmack dieser Garnele. ",
