    "desc_de": "Ein rundum weißer Tintenfisch, der bis zu 2 Fulme groß werden kann. In der Laichzeit versammeln sie sich in der Rubinsee und verstecken ihre geleeartigen Eier zwischen den Felsen und Riffen. ",
