    "desc_de": "Sie ist in den Gewässern Yanxias beheimatet, wobei sie besonders häufig an den Stängeln von Seepflanzen und Schilf in heißen Quellen anzutreffen ist. Während der Fortpflanzungszeit verändert sich das Verhalten der Männchen schlagartig. Sie können dann häufig in der Nähe der Was­ser­o­ber­flä­che beobachtet werden, wo sie in der Hoffnung, einen Partner zu finden, Wasser aufplatschen lassen.",
