    "desc_de": "Eine von der Armee des Kaiserreiches eingeschleppte Spezies. Die unterdrückten Bewohner Yanxias haben als unauffällige Geste des Protests die unkontrollierte Vermehrung dieses Barsches durch stetiges Fischen aufhalten können.",
