    "desc_de": "Ihr Fleisch und Blut wird wegen ihrer angeblich heilenden Wirkung zu hohen Preisen gehandelt. Der Gebrauch der Einwohner Yanxias, das frische Blut dieser Schildkröte als Medizin zu trinken, wurde unter der Herrschaft des Kaiserreichs als barbarische Sitte abgetan und verboten.",
