    "id": 40521,
    "name_de": "Rosafarbene Garnele",
    "desc_de": "Eine durch ihre Färbung leicht auffallende Garnelenart, welche besonders häufig in den Gewässern rund um den Äquator aufzufinden ist. Ihre Schale und Zangen sind weich genug, um sie zu zerkauen, weshalb sie oft in Pulverform für hiesiges Gebäck verwendet werden.",
