    "desc_de": "Es besteht der Glaube, dass dieser Fisch zusammen mit dem Gesang der Sirenen erscheint. Als „singender Fisch“ bekannt, gilt er deshalb als ein Omen für Unglück in den Augen so manches Seefahrers.",
