    "desc_de": "Diese Tintenfischart wird dank ihres weißen, spitz zulaufenden Kopfes häufig mit Speeren verglichen. Neben ihrem Status als Glücksbringer unter Speernutzern wird sie auch in getrockneter Form als Delikatesse hoch geschätzt.",
