    "desc_de": "Eine Qualle, welche durchgehend ein schwaches Leuchten von sich gibt. Aufgrund ihrer äußerlichen Ähnlichkeit mit einer Papierlaterne wird sie ab und zu mit einem Laternengeist verwechselt.",
