    "desc_de": "Mit ihren rot-weiß gefärbten Körpern ahmen diese Seepferdchen das Aussehen der in den selben Gewässern heimischen Gefleckten Garnele nach. Legenden besagen, dass der sagenumwobene Rubindrache ursprünglich dieser Art angehörte.",
