    "desc_de": "Dieser eigentlich hübsch anzusehende Tropenfisch ist eine invasive Art, die mit den Phantomströmungen aus fernen Meeren gekommen ist. Schwärme sehen aus wie ein leuchtend gelber Blumengarten, doch dieses Schmuckstück warnt in der Regel vor extremem Wetter.",
