    "desc_de": "Eine Unterart der Einzig-Garnele, deren Panzer sich im Laufe der Zeit zu einem satten, dunklen Grün verfärbt hat. Benannt nach den Einsiedlern, die ein zurück­gezogenes Leben auf der Gensui-Gipfelkette führen.",
