    "desc_de": "Die Phantomströmungen verleihen den Schuppen der Kristallforelle ihre charakteristische Färbung, die von Kunsthandwerkern aus dem Fernen Osten besonders geschätzt wird. Sie wird üb­lich­er­wei­se dann gefangen, wenn ihre Schuppen am intensivsten schimmern.",
