    "desc_de": "Namazuo, die ihre Tage damit verbringen, im Schlamm zu faulenzen, entwickeln sich nach und nach in ihren Urzustand zurück. Dieses Phänomen ist zwar selten, aber erinnert faule Namazuo regelmäßig an ihr drohendes Schicksal.",
