    "name_de": "Gakugyo",
    "desc_de": "Eine uralte fernöstliche Legende besagt, dass einst ein weißes Kaninchen vom Mond den großen Fluss überquerte, indem es Fische aneinanderreihte und als Brücke benutzte. Der Gakugyo kann es seitdem kaum erwarten, das weiße Kaninchen wiederzusehen, und es mit Haut und Haar zu verschlingen.",
