    "desc_de": "Eine Gasame, die zusammen mit ihren Artgenossen am Krabbenkocher lebte, wo ihre Panzer durch Lava gehärtet wurden. So konnte sie sich zwar besser gegen Feinde schützen, aber muss regelmäßig bis auf den Meeresboden tauchen, um ihren glühend heißen Panzer abzukühlen.",
