    "name_de": "Gonzalos Güte",
    "desc_de": "Diese Schnecke wurde durch eine Sage aus Kholusia getauft: Eines Tages stürzte ein Prinz tief hinab ins Meer, doch sie nahm sich seiner an und brachte ihn zurück nach oben. Genügsam wie sie ist, verzichtete sie auf jegliche Ehren der Oberfläche und kehrte lieber ins kühle Nass zurück.",
