    "desc_de": "Aufgrund seiner hohen Lebenserwartung wird dieser Fisch häufig als Testsubjekt in der Erforschung von Wasserqualität verwendet. Wissenschaftler geben ihnen je nach Ge­sichts­aus­druck gerne lustige Spitznamen.",
