    "desc_de": "Dieser Todeswurm lebt bevorzugt in den Tiefen der Grotte. Die toxischen Effekte der stetig auf die Was­ser­o­ber­flä­che hinabschwebenden Pilzsporen sollen dazu geführt haben, dass dieses Wesen auf dem Grund in Neonfarben vor sich hin schimmert.",
