    "desc_de": "Dieser Süßwasser-Hering ist reich an Eiweiß und äußerst schmackhaft obendrauf. Als Katzenfutter ist er äußerst beliebt, wobei allein der Geruch selbst die verwöhnteste Großstadtmieze verrückt werden lässt.",
