    "name_de": "Güldensternerner Hummer",
    "desc_de": "Um sich im All vor Ätherstrudeln zu schützen, ist seine Schale von einer Art güldenem Film überzogen. Gekocht verbreitet diese Vergoldung einen exotisch-aromatischen Duft, bevor sie sich abpellt und essbares Fleisch zum Vorschein bringt.",
