    "id": 41300,
    "name_de": "Schatz-Guppy",
    "desc_de": "Der Kristall­exarch selbst gab diesem Fisch bei einem Besuch des Feenreichs seinen Namen, als er sich an die Schönheit des Meeres in seiner Heimat erinnerte. Bei den Bewohnern Norvrandts erweckt dieser Fisch auch Erinnerungen an die Landschaft der südlichen Gewässer, welche während der Lichtflut verloren gingen.",
