    "name_de": "Fathric-Steinkopf",
    "desc_de": "Dieser Fisch ist nach dem Oberhaupt der Kirche des Strahlenden Lichts benannt. Fathric galt als äußerst sturer Geselle, wodurch sich auch der Grund für die Namenswahl dieses steinharten Fisches erklären lässt.",
