    "id": 41409,
    "name_de": "Schnee-Parexus",
    "desc_de": "Seine mit Dornen übersäten Flossen schützen ihn vor größeren Fressfeinden. Das an Schneeflocken erinnernde Muster auf seiner Haut stammt von Äther-Aktivitäten im ungefrorenen Wasser und hilft ihm bei der Tarnung.",
