    "name_de": "Pel-Frosch",
    "desc_de": "Eine Froschart, die goldenen Ornamenten ähnelt und bei den Pelupelu als ein Vorbote für Reichtum gilt. Abergläubische Pelupelu tragen die Tiere in Töpfen mit sich herum und hoffen auf den großen Profit.",
