    "id": 43666,
    "name_de": "Reifrock-Salmler",
    "desc_de": "Diese Salmler-Art umgibt dank ihrer silbrigen Schuppen und der schwarzen Flossen ein Hauch von Eleganz. Das Wesen des Fisches ist allerdings eher stürmisch, wie Kinder aus Tuliyollal leidvoll bezeugen können: Man trifft kaum auf eins, das nicht schon einmal von einem gebissen wurde.",
