    "name_de": "Sternnebel-Garnele",
    "desc_de": "Diese Garnelenart aus der Sternnebel-See ist ein beliebtes Grundnahrungsmittel. In Tuliyollal wird sie gerne frittiert und dann in allerlei deftige Soßen getunkt.",
