    "name_de": "Kurznasenmakrele",
    "desc_de": "Der silbrige Körper dieses schreckhaften Salz­was­ser­fisches ist mit tintenähnlichen Flecken übersät. Das kleinste Anzeichen von Gefahr lässt ihn in Spalten oder an anderen dunklen Plätzen Zuflucht suchen.",
