    "id": 43673,
    "name_de": "Blaubörse",
    "desc_de": "Die feinen Schuppen dieses Fisches wirken dank ihres Goldrandes wie übereinanderliegende Münzen, was ihm das Aussehen einer prall gefüllten Geldbörse verleiht.",
