    "name_de": "Goldflossen-Cavalla",
    "desc_de": "Die goldene Flosse dieses Salz­was­ser­fisches wird oft mit der Spitze einer Hellebarde verglichen. Man bezeichnet ihn deshalb auch als Wächter des Hafens von Tuliyollal, weshalb er von den Seeleuten der Hauptstadt verehrt wird.",
