    "name_de": "See-Alpaka",
    "desc_de": "In Seen beheimatet, die einst mit dem Meer verbunden waren, bevorzugt diese Fischart salzhaltiges Wasser. Ihren Namen verdankt sie der entfernten Ähnlichkeit zur gleichnamigen Reittierart.",
