    "name_de": "Urqo-Frosch",
    "desc_de": "Diese in Karvarhur der Ersten, beheimateten Amphibien werden im Durchschnitt nicht größer als eine Handspanne. Es wurden jedoch auch schon umfangreichere Exemplare beobachtet, von denen einige breiter als die Hüfte eines Pelupelu wurden. Zugegebenerweise ist das kein Maß, das Ehrfurcht einflößt.",
