    "name_de": "Zeh Tortoh",
    "desc_de": "Grob übersetzt bedeutet der Yok Huy-Name dieses Was­ser­be­woh­ners „Fisch der nie endenden Blüten“. Ein passender Name für eine Kreatur, die so viel Ähnlichkeit mit einem zarten Blütenblatt hat.",
