    "name_de": "Kozama'uka-Skipper",
    "desc_de": "Dieser wendige Fisch nutzt seine breiten, segelartigen Flossen, um von einem Wasserweg in den nächsten zu springen. Man nimmt an, dass dieses Verhalten entstanden ist, um neue Beutegebiete zu erschließen.",
