    "name_de": "Bopo'u-Schläfer",
    "desc_de": "Wenn man diesen Fisch im Schlamm sieht, nimmt man schnell an, dass er schläft. In Wirklichkeit aber hält er nur vollkommen still und wartet darauf, sich auf seine unglückliche Beute zu stürzen.",
