    "name_de": "Falten-Matamata",
    "desc_de": "Diese sanfte Schildkröte ist in ihrem natürlichen Lebensraum zwischen herabgefallenen Blättern und Steinen gut getarnt. Der Name des Tieres kommt von den gefalteten Erhebungen, die seinen Panzer zieren.",
