    "name_de": "Treibholz-Katfisch",
    "desc_de": "Dank des rindenartigen Musters an seinen Seiten, kann sich dieser Fisch hervorragend zwischen Treibholz und herabgefallenen Ästen verstecken. Vor allem die Hanuhanu betrachten das zarte, fette Fleisch dieses Fisches als Delikatesse.",
