    "name_de": "Bronze-Pleco",
    "desc_de": "Die rötliche Haut dieses Fisches, der den Grund von Gewässern nach Nahrung absucht, hat eine matte, metallische Erscheinung. Er hält sich bevorzugt zwischen Felsen und Baumstämmen auf und ernährt sich hauptsächlich von Algen.",
