    "desc_de": "Ein dünner, länglicher Cichlide aus den Gewässern Turals. Seine Flossen gleichen wunderschönen Häkelarbeiten, doch aufgrund seines stark ausgeprägten Kampftriebes sind sie leider meist zerrissen.",
