    "desc_de": "Ein überaus angriffslustiger Fleischfresser, dessen Unterkiefer mit zwei spitzen Fangzähnen ausgestattet ist. Für die Jagd springt er auch gerne Beute an Land an, wodurch ihm in der Ver­gangen­heit nicht wenige Pelupelu zum Opfer gefallen sind. ",
