    "desc_de": "Auch wenn sich Bitterlinge in ganz Yok Tural finden lassen, heben sich die Exemplare in Ku'uxage durch ihre einzigartige Jagdtechnik von ihren Artgenossen ab. Sie jagen primär Insekten um Wasserfälle, indem sie mit hoher Ge­schwindig­keit aus dem Wasser schnellen.",
