    "desc_de": "Ein Fisch, der an den auf Tural angebauten Mais erinnert. Nicht nur ist sein Körper rundlich geformt und von gelber Färbung, sondern wie sein Namensgeber wird auch er selbst gerne als Nahrungsmittel verwendet.",
