    "desc_de": "Ein lebhafter Süßwasserfisch, heimisch in den Gewässern des Ligaka-Bruchs. Seinen Namen erhielt er von Naturforschern aus Sharlayan, die womöglich auch aufgrund ihres höheren Alters recht unkreativ bei der Benennung vorgingen.",
