    "desc_de": "Eine kleine Süßwasserart mit einer beachtlich großen Rückenflosse. Sie erhielt ihren auf den ersten Blick ungewöhnlichen, aber durchaus passenden Namen von den Hanuhanu, die sie gerne zu Knödeln verarbeiten.",
