    "name_de": "Oxydoras",
    "desc_de": "Die Seiten dieses Welses sind mit nadelähnlichen Höckern gespickt. Diese Besonderheit mag dazu verleiten, ihn beim Schwanz zu greifen und als Keule zu verwenden, doch hiervon wird stark abgeraten.",
