    "desc_de": "Ein Mitglied der Familie der Rochen, welcher das Lagaka-Bruch seine Heimat nennt. Seine Augen sind inmitten seines charakteristisch weiß gefleckten Musters nur schwer zu erkennen, wodurch potenzielle Fressfeinde getäuscht werden können.",
