    "name_de": "Schaufelnasen-Wels",
    "desc_de": "Diese Welsart nutzt ihr spitz zulaufendes Maul, um den Flussboden umzugraben und so nach Insekten und Mikroben zu suchen. Gleichzeitig sorgt ihr langer Bart dafür, den aufgewirbelten Sand wieder zu glätten.",
