    "name_de": "Glitzerfisch",
    "desc_de": "Trifft Sonnenlicht auf die gleißend silbernen Schuppen dieses Was­ser­be­woh­ners, so beginnt er leicht rot zu pulsieren. Die hierdurch entstehenden Lichtspuren im Wasser sind so verschwommen, dass sich ein einzelner dieser Art leicht mit einem Schwarm verwechseln lässt.",
