    "name_de": "Ut'ohmu-Dämmerfisch",
    "desc_de": "Ein bekannter Dichter schrieb einst über die Färbung dieses Fisches, sie „gleiche den Strahlen der Morgensonne, die den Horizont von Ut'ohmu erhellen“, wodurch er zu seinem Namen kam. ",
