    "desc_de": "Der Rücken dieser Art ist geprägt von einer kastanienbraunen Färbung, während seine Bauchregion eher weißlich erscheint. Ist diese Art auch mit den Killifischen verwandt, so ist sie den meisten Leuten dafür geläufig, eine Größe vergleichbar mit der Pranke eines Xbr'aal ereichen zu können.",
