    "desc_de": "Ein anmutiger Süßwasserfisch, dessen verhältnismäßig dicke Rückenflosse stark an das Segel eines Bootes erinnert. Er schwimmt bevorzugt durch die Ufergewässer ruhiger Buchten.",
