    "name_de": "Hunmu Ob",
    "desc_de": "Übersetzt aus der Sprache der Xbr'aal bedeutet der Name dieses Was­ser­be­woh­ners in etwa „Weißes Versteck“, was auf sein charakteristisches Strei­fen­mus­ter zurückzuführen ist. An sonnigen Tagen sorgt dieses für eine perfekte Tarnung unter der Was­ser­o­ber­flä­che.",
