    "desc_de": "Seine eher abstoßende Form lässt ihn wie eine Mischung aus Wurm und Schlange erscheinen. Wenn er sich bedroht fühlt, sondert dieser uralte Lurch einen giftigen Schleim ab, um Jäger fernzuhalten.",
