    "name_de": "Spiegelkarpfen",
    "desc_de": "Mit matten, spiegelähnlichen Schuppen geschmückt, die Treibholz und andere Gegenstände im Wasser reflektieren, sodass er sich besser verstecken kann. Er ist ein äußerst sanfter Zeitgenosse und bewegt sich mit ruhiger Anmut durch seine Gewässer.",
