    "name_de": "Tsoly Mu",
    "desc_de": "In der Sprache der Xbr'aal bedeutet „mu“ „Sonne“, während „tsoly“ sich auf einen Cenote bezieht. Ein passender Name für diesen leuchtend roten Fisch, der in den Tiefen oft irrtürmlich für eine mysteriöse Lichtquelle gehalten wird.",
