    "name_de": "Iq Rrax-Blattfisch",
    "desc_de": "Dieser Fisch soll seine Tarnung gefunden haben, als eine Flut fahler Blätter von der Aschenfront von Xobr'it in die Gewässer des Iq Rrax Tsoly floss. Für das ungeübte Auge ist er jedenfalls kaum von einem verkohlten, im Wasser treibenden Blatt zu unterscheiden.",
