    "name_de": "Meerengel-Mutter",
    "desc_de": "Mit seinen majestätischen, flügelartigen Flossen und seiner gedeckten Färbung hat dieser Fisch eine fast ätherische Ausstrahlung. Während ähnliche Arten überall auf der Welt zu finden sind, hat sich diese seit Urzeiten nicht verändert.",
