    "desc_de": "Dieser uralte Fisch ist in metallisch glänzende Schuppen gehüllt. Sie sollen im Zeitalter des Konflikts zwischen den Mamool Ja und den Xbr'aal für die Herstellung von Plattenrüstungen und anderen Schutzausrüstungen verwendet worden sein.",
