    "name_de": "Trübaugen-Karpfen",
    "desc_de": "Als relativ neue Entdeckung in der Fauna von Tural gibt es noch viel über diesen mysteriösen Karpfen zu lernen. Da er nicht über Augen verfügt, scheint er sich mit einer Reihe anderer Sinne in seiner Umgebung zurechtzufinden.",
