    "name_de": "Xobr'it-Hummer",
    "desc_de": "Die Vorfahren dieses geisterhaften Hummers hatten einst rötlich-braune Panzer. Im Zuge der wütenden Brände des Krieges in der Umgebung ihres Lebensraums, machte diese Art eine tiefgreifende Veränderung durch - die überschüssige Asche in der Atmosphäre ließ ihre Panzer weiß-grau erbleichen.",
