    "name_de": "Goldener Axolotl",
    "desc_de": "Der Kragen um den Kopf dieses Lurches erinnert zusammen mit seinem goldenen Glanz an Sonnenstrahlen. Gelehrte vermuten, dass die Motive, die einige der Ruinen in der Region zieren, ebenso von dieser Kreatur inspiriert sind wie von der Sonne selbst.",
