    "name_de": "Hornfrosch",
    "desc_de": "Der bräunliche Körper dieses Frosches hilft ihm, sich unter abgefallenen Blättern und anderer toter Vegetation zu verstecken. Er ist leicht an den Fortsätzen über den Augen zu erkennen und soll es verabscheuen, wenn man sich über seine Hörner lustig macht.",
