    "desc_de": "Es ist zwar nicht genug, um ihn im Dunkeln sehen zu können, doch sind die Schuppen dieses Fisches kunterbunt und gelten als wunderschön. In der Laichsaison kehrt er nach Xty'iinbek Tsoly zurück.",
