    "desc_de": "Diese Haifischart ist eigentlich in den Indigotiefen beheimatet. Doch nachdem es einige Exemplare auf der Beutejagd bis ins Innere der Cenoten trieb, scheinen sie sich eingelebt und verbreitet zu haben.",
