    "desc_de": "Seinem Namensvetter, dem Gott des Wohlstands, gerecht werdend, soll dieser Frosch neugierigen Reisenden angeblich den Weg zur sagen­umwobenen Stadt aus Gold weisen. Ein Irrglaube, der darauf basiert, dass das Gift, welches der Amphibie innewohnt, eine erhöhte Lichtempfindlichkeit hervorrufen und somit die Welt in einem goldenen Glanz erscheinen lassen kann.",
