    "desc_de": "Der Name dieses gewaltigen Störs bedeutet so viel wie „der, der die Morgenröte trinkt“. Auch wenn sie ähnlich schwarz gefärbt wie die seiner deutlich kleineren Artgenossen sind, weisen seine Eier ein derart schweres Gewicht auf, dass sie auf den Grund des Toari sinken, und seine frischgeschlüpften Jungen beim Schwimmen an die Was­ser­o­ber­flä­che von den Einheimischen für Seegeister gehalten wurden.",
